mapper.select:
select l.id, l.operate_emp_id, l.operation_time, l.class_name, l.method_name, l.args, l.result, l.cost_time from log l left join emp e on l.operate_emp_id = e.id
and e.name like concat('%', #{queryParam.operatorName}, '%')
and l.class_name like concat('%', #{queryParam.className}, '%')
and l.operation_time between #{queryParam.beginTime} and #{queryParam.endTime}
order by l.operation_time desc limit #{start}, #{pageSize}
